#include "pvdg_ui_export_control.h"
#include <errno.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "pvdg_ui_theme.h"
typedef struct {lv_obj_t *root,*badge,*message,*policy,*orientation,*export_limit,*minimum_import,*save,*refresh,*keyboard,*confirm,*confirm_text,*confirm_save;pvdg_ui_source_config_t config;pvdg_ui_export_control_callbacks_t callbacks;bool config_available,write_allowed,busy;} export_ui_t;static export_ui_t s;
static lv_obj_t *lab(lv_obj_t*p,const char*t,uint32_t c,const lv_font_t*f){lv_obj_t*o=lv_label_create(p);lv_label_set_text(o,t?t:"");pvdg_ui_style_label(o,lv_color_hex(c),f);return o;}static lv_obj_t *row(lv_obj_t*p,const char*n){lv_obj_t*r=lv_obj_create(p);pvdg_ui_style_root(r);lv_obj_set_width(r,LV_PCT(100));lv_obj_set_height(r,50);lv_obj_set_layout(r,LV_LAYOUT_FLEX);lv_obj_set_flex_flow(r,LV_FLEX_FLOW_ROW);lv_obj_set_flex_align(r,LV_FLEX_ALIGN_SPACE_BETWEEN,LV_FLEX_ALIGN_CENTER,LV_FLEX_ALIGN_CENTER);lv_obj_t*l=lab(r,n,PVDG_UI_COLOR_MUTED,PVDG_UI_FONT_BODY);lv_obj_set_width(l,250);return r;}static void kb_hide(void){if(!s.keyboard)return;lv_keyboard_set_textarea(s.keyboard,NULL);lv_obj_add_flag(s.keyboard,LV_OBJ_FLAG_HIDDEN);}static void kb_event(lv_event_t*e){lv_event_code_t c=lv_event_get_code(e);if(c==LV_EVENT_READY||c==LV_EVENT_CANCEL)kb_hide();}static void field_event(lv_event_t*e){if(!s.keyboard)return;lv_obj_t*f=lv_event_get_target_obj(e);lv_keyboard_set_textarea(s.keyboard,f);lv_obj_remove_flag(s.keyboard,LV_OBJ_FLAG_HIDDEN);lv_obj_move_foreground(s.keyboard);}static lv_obj_t *text_field(lv_obj_t*p,const char*n){lv_obj_t*r=row(p,n),*f=lv_textarea_create(r);lv_textarea_set_one_line(f,true);lv_obj_set_size(f,240,40);lv_obj_add_event_cb(f,field_event,LV_EVENT_FOCUSED,NULL);lv_obj_add_event_cb(f,field_event,LV_EVENT_CLICKED,NULL);return f;}static lv_obj_t *drop_field(lv_obj_t*p,const char*n,const char*o){lv_obj_t*r=row(p,n),*d=lv_dropdown_create(r);lv_dropdown_set_options(d,o);lv_obj_set_width(d,240);return d;}static lv_obj_t *btn(lv_obj_t*p,const char*t,lv_event_cb_t cb){lv_obj_t*b=lv_button_create(p);lv_obj_set_height(b,PVDG_UI_TOUCH_MIN);lv_obj_t*l=lab(b,t,PVDG_UI_COLOR_TEXT,PVDG_UI_FONT_BODY);lv_obj_center(l);lv_obj_add_event_cb(b,cb,LV_EVENT_CLICKED,NULL);return b;}static bool get_double(lv_obj_t*f,double*v){const char*t=lv_textarea_get_text(f);char*e=NULL;errno=0;double x=strtod(t?t:"",&e);if(errno||!e||e==t||*e||!isfinite(x)||x<0.0||x>PVDG_UI_SOURCE_KW_MAX)return false;*v=x;return true;}static void set_double(lv_obj_t*f,double v){char t[32];snprintf(t,sizeof(t),"%.3f",v);lv_textarea_set_text(f,t);}static bool build_candidate(pvdg_ui_source_config_t*out,char*error,size_t n){if(!s.config_available){snprintf(error,n,"Load current Solar-Grid configuration first.");return false;}*out=s.config;out->policy=(pvdg_ui_source_policy_t)lv_dropdown_get_selected(s.policy);out->meter_orientation=(pvdg_ui_source_meter_orientation_t)lv_dropdown_get_selected(s.orientation);if(!get_double(s.export_limit,&out->export_limit_kw)||!get_double(s.minimum_import,&out->minimum_import_kw)){snprintf(error,n,"Export limits must be finite values from 0 to 1,000,000 kW.");return false;}return pvdg_ui_source_config_validate(out,error,n)==PVDG_UI_SOURCE_CONFIG_OK;}static void confirm_close(void){if(s.confirm)lv_obj_add_flag(s.confirm,LV_OBJ_FLAG_HIDDEN);}static void cancel_event(lv_event_t*e){(void)e;confirm_close();}static void confirm_event(lv_event_t*e){(void)e;if(s.busy||!s.write_allowed||!s.callbacks.submit_config)return;pvdg_ui_source_config_t c;char error[192];if(!build_candidate(&c,error,sizeof(error))){confirm_close();pvdg_ui_label_set_if_changed(s.message,error);return;}s.callbacks.submit_config(&c,s.callbacks.user);confirm_close();}static void save_event(lv_event_t*e){(void)e;if(s.busy||!s.write_allowed)return;pvdg_ui_source_config_t c;char error[192];if(!build_candidate(&c,error,sizeof(error))){pvdg_ui_label_set_if_changed(s.message,error);return;}lv_obj_remove_flag(s.confirm,LV_OBJ_FLAG_HIDDEN);lv_obj_move_foreground(s.confirm);}static void refresh_event(lv_event_t*e){(void)e;if(!s.busy&&s.callbacks.request_config)s.callbacks.request_config(s.callbacks.user);}
static void create_confirm(void){s.confirm=lv_obj_create(lv_layer_top());lv_obj_set_size(s.confirm,LV_PCT(100),LV_PCT(100));lv_obj_set_style_bg_opa(s.confirm,LV_OPA_90,LV_PART_MAIN);lv_obj_t*c=pvdg_ui_make_card(s.confirm);lv_obj_set_size(c,570,220);lv_obj_align(c,LV_ALIGN_CENTER,0,0);lv_obj_set_layout(c,LV_LAYOUT_FLEX);lv_obj_set_flex_flow(c,LV_FLEX_FLOW_COLUMN);lab(c,"Confirm Export Control Save",PVDG_UI_COLOR_WARNING,PVDG_UI_FONT_TITLE);s.confirm_text=lab(c,"Saving export control forces automatic control disabled and requires restart. Continue?",PVDG_UI_COLOR_TEXT,PVDG_UI_FONT_BODY);lv_obj_set_width(s.confirm_text,LV_PCT(100));lv_label_set_long_mode(s.confirm_text,LV_LABEL_LONG_WRAP);lv_obj_t*a=lv_obj_create(c);pvdg_ui_style_root(a);lv_obj_set_width(a,LV_PCT(100));lv_obj_set_height(a,PVDG_UI_TOUCH_MIN);lv_obj_set_layout(a,LV_LAYOUT_FLEX);lv_obj_set_flex_flow(a,LV_FLEX_FLOW_ROW);s.confirm_save=btn(a,"Save + Disable Control",confirm_event);lv_obj_set_flex_grow(s.confirm_save,1);lv_obj_t*cancel=btn(a,"Cancel",cancel_event);lv_obj_set_flex_grow(cancel,1);lv_obj_add_flag(s.confirm,LV_OBJ_FLAG_HIDDEN);}
lv_obj_t *pvdg_ui_export_control_create(lv_obj_t*parent,const pvdg_ui_export_control_callbacks_t*callbacks){memset(&s,0,sizeof(s));if(callbacks)s.callbacks=*callbacks;pvdg_ui_theme_init();s.root=lv_obj_create(parent);pvdg_ui_style_root(s.root);lv_obj_set_size(s.root,LV_PCT(100),LV_PCT(100));lv_obj_set_layout(s.root,LV_LAYOUT_FLEX);lv_obj_set_flex_flow(s.root,LV_FLEX_FLOW_COLUMN);lv_obj_set_style_pad_all(s.root,PVDG_UI_GAP_MD,LV_PART_MAIN);lv_obj_t*h=lv_obj_create(s.root);pvdg_ui_style_root(h);lv_obj_set_width(h,LV_PCT(100));lv_obj_set_height(h,48);pvdg_ui_make_title(h,"Export Control");s.badge=pvdg_ui_make_badge(h,"Unavailable",lv_color_hex(PVDG_UI_COLOR_INACTIVE));lv_obj_t*a=lv_obj_create(s.root);pvdg_ui_style_root(a);lv_obj_set_width(a,LV_PCT(100));lv_obj_set_height(a,PVDG_UI_TOUCH_MIN);lv_obj_set_layout(a,LV_LAYOUT_FLEX);lv_obj_set_flex_flow(a,LV_FLEX_FLOW_ROW);s.refresh=btn(a,"Refresh",refresh_event);s.save=btn(a,"Validate + Save",save_event);s.message=lab(a,"Load current policy before editing.",PVDG_UI_COLOR_MUTED,PVDG_UI_FONT_BODY);lv_obj_set_flex_grow(s.message,1);lv_obj_t*card=pvdg_ui_make_card(s.root);lv_obj_set_width(card,LV_PCT(100));lv_obj_set_flex_grow(card,1);lv_obj_set_layout(card,LV_LAYOUT_FLEX);lv_obj_set_flex_flow(card,LV_FLEX_FLOW_COLUMN);s.policy=drop_field(card,"Policy","Zero Export\nLimited Export\nMinimum Import");s.orientation=drop_field(card,"Meter sign","Import positive\nExport positive");s.export_limit=text_field(card,"Limited export limit (kW)");s.minimum_import=text_field(card,"Minimum import target (kW)");s.keyboard=lv_keyboard_create(s.root);lv_obj_set_size(s.keyboard,LV_PCT(100),190);lv_obj_add_event_cb(s.keyboard,kb_event,LV_EVENT_READY,NULL);lv_obj_add_event_cb(s.keyboard,kb_event,LV_EVENT_CANCEL,NULL);lv_obj_add_flag(s.keyboard,LV_OBJ_FLAG_HIDDEN);create_confirm();if(s.callbacks.request_config)s.callbacks.request_config(s.callbacks.user);return s.root;}
void pvdg_ui_export_control_set_config(const pvdg_ui_source_config_t*c){if(!s.root||!c)return;s.config=*c;s.config_available=true;lv_dropdown_set_selected(s.policy,(uint16_t)c->policy);lv_dropdown_set_selected(s.orientation,(uint16_t)c->meter_orientation);set_double(s.export_limit,c->export_limit_kw);set_double(s.minimum_import,c->minimum_import_kw);char e[192];pvdg_ui_source_config_result_t r=pvdg_ui_source_config_validate(c,e,sizeof(e));pvdg_ui_badge_set(s.badge,r==PVDG_UI_SOURCE_CONFIG_OK?"Schema 4 valid":"Config invalid",lv_color_hex(r==PVDG_UI_SOURCE_CONFIG_OK?PVDG_UI_COLOR_SUCCESS:PVDG_UI_COLOR_DANGER));}
void pvdg_ui_export_control_apply_state(const pvdg_ui_export_control_state_t*st){if(!s.root)return;s.config_available=st&&st->config_available&&s.config_available;s.write_allowed=st&&st->write_allowed;s.busy=st&&st->busy;if(st&&st->message&&st->message[0])pvdg_ui_label_set_if_changed(s.message,st->message);if(!s.config_available||!s.write_allowed||s.busy)lv_obj_add_state(s.save,LV_STATE_DISABLED);else lv_obj_remove_state(s.save,LV_STATE_DISABLED);}
